// Sound effects synthesised with WebAudio: no audio files to load.

export class Sfx {
  private ctx: AudioContext | null = null;
  muted = false;

  /** browsers only allow audio after a tap or key press: call this from one */
  unlock(): void {
    if (this.muted) return;
    try {
      if (!this.ctx) {
        const AC =
          window.AudioContext ??
          (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (!AC) return;
        this.ctx = new AC();
      }
      if (this.ctx.state === 'suspended') void this.ctx.resume();
    } catch {
      this.ctx = null;
    }
  }

  private tone(
    from: number,
    to: number,
    dur: number,
    wave: OscillatorType = 'square',
    vol = 0.06,
    delay = 0,
  ): void {
    const ctx = this.ctx;
    if (!ctx || this.muted || ctx.state !== 'running') return;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = wave;
    osc.frequency.setValueAtTime(from, t0);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain).connect(ctx.destination);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  jump(air: boolean): void {
    this.tone(air ? 520 : 360, air ? 880 : 620, 0.12, 'square', 0.04);
  }
  coin(): void {
    this.tone(1250, 1700, 0.07, 'triangle', 0.06);
  }
  item(): void {
    this.tone(520, 1040, 0.16, 'triangle', 0.08);
    this.tone(780, 1560, 0.16, 'triangle', 0.06, 0.08);
  }
  hit(): void {
    this.tone(220, 60, 0.28, 'sawtooth', 0.09);
  }
  block(): void {
    this.tone(900, 500, 0.14, 'triangle', 0.08);
  }
  bank(): void {
    [660, 880, 1100, 1320].forEach((f, i) => {
      this.tone(f, f, 0.12, 'triangle', 0.07, i * 0.07);
    });
  }
  skip(tier: number): void {
    this.tone(300 + tier * 90, 700 + tier * 160, 0.22, 'sawtooth', 0.05);
  }
  /** an airdropped money bag */
  bag(): void {
    this.tone(180, 90, 0.08, 'square', 0.06);
    [988, 1319, 1568].forEach((f, i) => {
      this.tone(f, f * 1.01, 0.09, 'triangle', 0.07, 0.03 + i * 0.045);
    });
  }
  /** a moon coin */
  moon(): void {
    this.tone(1400, 2100, 0.12, 'sine', 0.07);
    this.tone(2100, 2800, 0.14, 'sine', 0.05, 0.06);
  }
  /** off the whale's back; the blowhole throws much higher */
  bounce(spout: boolean): void {
    if (spout) {
      this.tone(160, 1200, 0.45, 'sine', 0.11);
      this.tone(500, 1800, 0.3, 'triangle', 0.05, 0.1);
    } else this.tone(180, 520, 0.14, 'sine', 0.09);
  }
  /** the rocket engine burning, played over and over while it does */
  thrust(): void {
    this.tone(110 + Math.random() * 40, 70, 0.1, 'sawtooth', 0.035);
  }
  rocket(): void {
    this.tone(120, 900, 0.7, 'sawtooth', 0.05);
  }
  /** the big bear, squeezed */
  bigStomp(): void {
    this.tone(200, 50, 0.3, 'square', 0.1);
    [523, 659, 784, 1047, 1319].forEach((f, i) => {
      this.tone(f, f * 1.02, 0.14, 'triangle', 0.08, 0.06 + i * 0.07);
    });
  }
  /** thrown up by the bull's horns */
  toss(): void {
    this.tone(140, 1400, 0.4, 'sawtooth', 0.07);
    this.tone(784, 1568, 0.2, 'triangle', 0.07, 0.12);
  }
  /** short squeeze: landed on a bear. Every one more in a row rings a little higher */
  stomp(chain = 1): void {
    const k = 1 + 0.16 * (Math.min(chain, 6) - 1);
    this.tone(260, 90, 0.1, 'square', 0.07);
    this.tone(700 * k, 1400 * k, 0.14, 'triangle', 0.07, 0.05);
  }
  /** a jet fires */
  shot(): void {
    this.tone(1900, 500, 0.09, 'sawtooth', 0.06);
    this.tone(900, 200, 0.07, 'square', 0.04, 0.02);
  }
  /** a wick strikes out of the sky: a crack and a short roll of thunder */
  strike(): void {
    this.tone(2600, 240, 0.1, 'sawtooth', 0.07);
    this.tone(130, 45, 0.32, 'square', 0.05, 0.05);
  }
  /** a bomb blows a candle out of the chart */
  bomb(): void {
    this.tone(180, 40, 0.35, 'sawtooth', 0.11);
    this.tone(90, 30, 0.45, 'square', 0.08, 0.03);
  }
  /** jets are coming in from the right: two quick warning beeps */
  flyer(): void {
    this.tone(1250, 980, 0.07, 'square', 0.045);
    this.tone(1250, 980, 0.07, 'square', 0.045, 0.12);
  }
  /** a hazard broken during a bull run */
  smash(): void {
    this.tone(200, 70, 0.14, 'sawtooth', 0.08);
    this.tone(1100, 1500, 0.08, 'triangle', 0.05, 0.04);
  }
  /** a close call over a wick */
  graze(): void {
    this.tone(1500, 2300, 0.07, 'sine', 0.06);
  }
  bull(): void {
    [392, 523, 659, 784, 1047].forEach((f, i) => {
      this.tone(f, f * 1.02, 0.14, 'sawtooth', 0.06, i * 0.06);
    });
  }
  /** a market event starts: a bright fanfare for good news, a falling one for bad */
  market(good: boolean): void {
    const notes = good ? [523, 659, 784, 1047] : [440, 370, 311, 233];
    notes.forEach((f, i) => {
      this.tone(f, f, 0.13, good ? 'triangle' : 'sawtooth', 0.08, i * 0.08);
    });
  }
  whale(): void {
    this.tone(90, 190, 0.6, 'sine', 0.12);
    this.tone(1300, 1900, 0.12, 'triangle', 0.05, 0.35);
    this.tone(1600, 2200, 0.12, 'triangle', 0.05, 0.47);
  }
  liquidated(): void {
    [440, 330, 247, 165].forEach((f, i) => {
      this.tone(f, f * 0.7, 0.22, 'sawtooth', 0.09, i * 0.16);
    });
  }
}
